class Solution {
public:
    long long minimumMoves(vector<int>& nums,int k,int maxChanges) {
        vector<long long> pos;
        int n=nums.size(),run=0,bestRun=0;
        for(int i=0;i<n;++i) {
            if(nums[i]) {pos.push_back(i); run++; bestRun=max(bestRun,run);}
            else run=0;
        }
        int natural=min(k,min(3,bestRun));
        long long best=LLONG_MAX;
        if(k-natural<=maxChanges) best=1LL*max(0,natural-1)+2LL*(k-natural);
        int need=k-maxChanges;
        if(need>0 && need<=(int)pos.size()) {
            vector<long long> pref(pos.size()+1);
            for(int i=0;i<(int)pos.size();++i) pref[i+1]=pref[i]+pos[i];
            for(int i=0;i+need<=(int)pos.size();++i) {
                int j=i+need-1,m=(i+j)/2;
                long long moves=pos[m]*(m-i)-(pref[m]-pref[i]);
                moves+=(pref[j+1]-pref[m+1])-pos[m]*(j-m);
                best=min(best,moves+2LL*maxChanges);
            }
        }
        return best;
    }
};
